/* ===================================================================== */

const I18n = {
  current: "es",

  /** Idioma inicial: guardado > navegador > español */
  detect() {
    const saved = localStorage.getItem("pedus_lang");
    if (saved && TRANSLATIONS[saved]) return saved;
    const browser = (navigator.language || "es").slice(0, 2).toLowerCase();
    return TRANSLATIONS[browser] ? browser : "es";
  },

  /** Cambia el idioma de toda la interfaz */
  setLanguage(lang, { persist = true } = {}) {
    if (!TRANSLATIONS[lang]) lang = "es";
    this.current = lang;
    if (persist) localStorage.setItem("pedus_lang", lang);
    document.documentElement.lang = lang;
    document.documentElement.dir = RTL_LANGUAGES.includes(lang) ? "rtl" : "ltr";
    this.apply();
    document.dispatchEvent(new CustomEvent("languagechange", { detail: { lang } }));
  },

  /** Traduce todos los elementos con atributos data-i18n* dentro de root */
  apply(root = document) {
    root.querySelectorAll("[data-i18n]").forEach((el) => { el.textContent = t(el.dataset.i18n); });
    root.querySelectorAll("[data-i18n-placeholder]").forEach((el) => { el.placeholder = t(el.dataset.i18nPlaceholder); });
    root.querySelectorAll("[data-i18n-title]").forEach((el) => {
      el.title = t(el.dataset.i18nTitle);
      if (!el.hasAttribute("aria-label")) el.setAttribute("aria-label", el.title);
    });
    root.querySelectorAll("[data-i18n-aria]").forEach((el) => { el.setAttribute("aria-label", t(el.dataset.i18nAria)); });
  },

  /** Código de idioma completo para voz/fechas */
  locale() {
    const map = { es: "es-ES", en: "en-US", fr: "fr-FR", de: "de-DE", it: "it-IT", pt: "pt-PT", ca: "ca-ES", ja: "ja-JP", zh: "zh-CN", ko: "ko-KR", ru: "ru-RU", ar: "ar-SA" };
    return map[this.current] || "es-ES";
  },
};

/** Función global de traducción con interpolación {variable} */
function t(key, vars = {}) {
  const dict = TRANSLATIONS[I18n.current] || TRANSLATIONS.es;
  let text = dict[key] ?? TRANSLATIONS.es[key] ?? key;
  for (const [name, value] of Object.entries(vars)) {
    text = text.split(`{${name}}`).join(String(value));
  }
  return text;
}
